package br.com.gamoravet.app;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.webkit.*;
public class MainActivity extends Activity {private WebView webView;@Override protected void onCreate(Bundle b){super.onCreate(b);createNotificationChannel();requestNotificationPermission();webView=new WebView(this);setContentView(webView);WebSettings s=webView.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);s.setDatabaseEnabled(true);s.setLoadsImagesAutomatically(true);s.setJavaScriptCanOpenWindowsAutomatically(false);s.setCacheMode(WebSettings.LOAD_NO_CACHE);webView.clearCache(true);webView.clearHistory();webView.addJavascriptInterface(new GamoraVetBridge(this),"GamoraVetAndroid");webView.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String url){super.onPageFinished(v,url);if(url!=null&&url.endsWith("index.html"))v.evaluateJavascript("(function(){var v='107';function add(src,next){var s=document.createElement('script');s.src=src+'?v='+v;s.onload=next||function(){};document.body.appendChild(s)}add('medications-enhancement.js',function(){add('medication-history-fix.js',function(){add('consultations-enhancement.js',function(){add('history-enhancement.js',function(){window.__GAMORAVET_ENHANCED__=true})})})})})();",null);}});webView.setWebChromeClient(new WebChromeClient());webView.setFocusable(true);webView.setFocusableInTouchMode(true);webView.requestFocus();webView.loadUrl("file:///android_asset/index.html");}private void createNotificationChannel(){if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.O){NotificationManager m=getSystemService(NotificationManager.class);NotificationChannel c=new NotificationChannel(NotificationReceiver.CHANNEL_ID,"Lembretes GamoraVet",NotificationManager.IMPORTANCE_HIGH);c.setDescription("Consultas, exames, vacinas, medicamentos e outros cuidados agendados");m.createNotificationChannel(c);}}private void requestNotificationPermission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},1001);}public static class GamoraVetBridge{private final Activity a;GamoraVetBridge(Activity a){this.a=a;}@JavascriptInterface public boolean notificationsAvailable(){return Build.VERSION.SDK_INT<33||a.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED;}@JavascriptInterface public void scheduleNotification(int id,long ts,String title,String text){if(ts<=System.currentTimeMillis())return;Intent i=new Intent(a,NotificationReceiver.class);i.putExtra("id",id);i.putExtra("title",title);i.putExtra("text",text);PendingIntent p=PendingIntent.getBroadcast(a,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=(AlarmManager)a.getSystemService(Context.ALARM_SERVICE);boolean daily=title!=null&&title.toLowerCase().contains("medicamento");if(daily)am.setRepeating(AlarmManager.RTC_WAKEUP,ts,AlarmManager.INTERVAL_DAY,p);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,ts,p);}@JavascriptInterface public void cancelNotification(int id){Intent i=new Intent(a,NotificationReceiver.class);PendingIntent p=PendingIntent.getBroadcast(a,id,i,PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(p!=null){AlarmManager am=(AlarmManager)a.getSystemService(Context.ALARM_SERVICE);am.cancel(p);p.cancel();}}@JavascriptInterface public void closeApp(){a.runOnUiThread(a::finish);}}@Override public void onBackPressed(){if(webView!=null)webView.evaluateJavascript("if(window.gamoraBack){window.gamoraBack();}else if(window.GamoraVetAndroid){GamoraVetAndroid.closeApp();}",null);else super.onBackPressed();}@Override protected void onDestroy(){if(webView!=null){webView.destroy();webView=null;}super.onDestroy();}}
